      '<exe_dir>/../lib — e.g. ~/.local/libsqlite3.dylib for '
      '~/.local/bin/fa. Reinstall fa (site/install.sh or install_local.sh) '
      'or run `fa update` to repair the layout; $path was not opened.]';
}

