    );
  }
  return (
    subPath: remainder.substring(0, queryIndex).replaceFirst(RegExp('^:+'), ''),
    queryString: remainder.substring(queryIndex + 1),
  );
}

/// Splits a `db.sqlite:table?query` reference into every plausible
